CREATE TABLE IF NOT EXISTS events(id uuid primary key,project_id uuid not null references projects(id) on delete cascade,severity text not null,message text not null,metadata jsonb not null default '{}',stack_trace text,environment text,service text,source text,request_id text,created_at timestamptz not null default now()); CREATE INDEX IF NOT EXISTS events_project_time_idx ON events(project_id,created_at desc); CREATE INDEX IF NOT EXISTS events_severity_idx ON events(project_id,severity,created_at desc);